<x-app-layout><div class="max-w-5xl p-6 mx-auto space-y-6"><div><h1 class="text-2xl font-bold">Buat Purchase Order</h1><p class="text-sm text-ink-500">Harga beli akan dipakai untuk memperbarui HPP rata-rata saat barang diterima.</p></div>@if($errors->any())<div class="p-4 text-sm text-red-700 bg-red-50 rounded-xl">{{ $errors->first() }}</div>@endif<form method="POST" action="{{ route('purchases.store') }}" class="space-y-5" x-data="{rows:[{product_id:'',quantity:1,unit_cost:0}]}">@csrf<div class="grid gap-4 p-5 bg-white border rounded-xl md:grid-cols-2"><label class="text-sm">Supplier<select name="supplier_id" class="block w-full mt-1 rounded-lg"><option value="">Pilih supplier</option>@foreach($suppliers as $s)<option value="{{ $s->id }}">{{ $s->name }}</option>@endforeach</select></label><label class="text-sm">Perkiraan tiba<input type="date" name="expected_at" class="block w-full mt-1 rounded-lg"></label></div><div class="p-5 space-y-3 bg-white border rounded-xl"><template x-for="(row,i) in rows" :key="i"><div class="grid gap-3 md:grid-cols-[1fr_150px_190px_44px]"><select :name="`items[${i}][product_id]`" x-model="row.product_id" class="rounded-lg" required><option value="">Pilih produk</option>@foreach($products as $p)<option value="{{ $p->id }}">{{ $p->product_name }} · {{ $p->base_unit ?? 'pcs' }}</option>@endforeach</select><input :name="`items[${i}][quantity]`" x-model="row.quantity" type="number" step="0.001" min="0.001" class="rounded-lg" placeholder="Qty" required><input :name="`items[${i}][unit_cost]`" x-model="row.unit_cost" type="number" min="0" class="rounded-lg" placeholder="Harga beli/unit" required><button type="button" @click="rows.splice(i,1)" class="rounded-lg bg-red-50 text-red-700">×</button></div></template><button type="button" @click="rows.push({product_id:'',quantity:1,unit_cost:0})" class="text-sm font-semibold text-primary-600">+ Tambah baris</button></div><textarea name="note" class="w-full rounded-xl" placeholder="Catatan pembelian"></